/**
 * The tick or cross shown after the docking animation: does the drug's best docking score clear
 * the binding threshold? Kept apart from the markup so it can be read and tested on its own.
 *
 * Vina docking scores are more negative for a better fit, so a drug "binds" when its score is at
 * or below the threshold. The score is a rough fit estimate, not a measured affinity
 * (`PoseScore` in the API schema), so the verdict is worded as a prediction.
 */

/**
 * The best docking score (more negative is better) at or below which a drug is predicted to bind.
 *
 * TODO: PROVISIONAL placeholder. Replace with the calibrated value once the team has it, and
 * delete this note. Until then every tick and cross is only as meaningful as this number.
 */
export const BINDING_SCORE_THRESHOLD = -7.0;

export type BindingVerdict = "binds" | "does_not_bind";

/** The verdict for a best docking score, or null when there is no score to judge. */
export function bindingVerdict(
  score: number | null,
  threshold: number = BINDING_SCORE_THRESHOLD,
): BindingVerdict | null {
  if (score === null || Number.isNaN(score)) return null;
  return score <= threshold ? "binds" : "does_not_bind";
}

import { describe, expect, it } from "vitest";
import { BINDING_SCORE_THRESHOLD, bindingVerdict } from "./bindingVerdict";

describe("bindingVerdict", () => {
  it("binds when the score is at or below the threshold (more negative is better)", () => {
    expect(bindingVerdict(-9.1, -7)).toBe("binds");
    expect(bindingVerdict(-7, -7)).toBe("binds");
  });

  it("does not bind when the score is above the threshold", () => {
    expect(bindingVerdict(-6.9, -7)).toBe("does_not_bind");
    expect(bindingVerdict(0, -7)).toBe("does_not_bind");
  });

  it("gives no verdict without a score, never a cross", () => {
    expect(bindingVerdict(null, -7)).toBeNull();
    expect(bindingVerdict(Number.NaN, -7)).toBeNull();
  });

  it("uses the shared threshold by default", () => {
    expect(bindingVerdict(BINDING_SCORE_THRESHOLD)).toBe("binds");
    expect(bindingVerdict(BINDING_SCORE_THRESHOLD + 0.1)).toBe("does_not_bind");
  });
});

/**
 * The motion of the docking animation as pure functions of time, so it can be tested without
 * WebGL. It is an illustration of the verdict, not a simulated trajectory: a drug that binds
 * glides in and settles in its docked pose; one that doesn't approaches, is turned away and
 * drifts back out.
 */
import type { BindingVerdict } from "../lib/bindingVerdict";

export interface DockFrame {
  /** How far from the start toward the docked pose, 0 at the start and 1 fully docked. */
  approach: number;
  /** How much of the starting tumble is left, 1 at the start and 0 when it has aligned. */
  tumble: number;
}

/** Milliseconds each animation takes. */
export const DOCK_DURATION_MS: Record<BindingVerdict, number> = {
  binds: 2600,
  does_not_bind: 3400,
};

/** How close a failed drug gets to the pocket before it is turned away (share of the way). */
export const REJECT_REACH = 0.72;
/** Where a failed drug comes to rest on its way back out (share of the way). */
export const REJECT_REST = 0.4;

const clamp01 = (x: number) => Math.min(1, Math.max(0, x));
const easeInOut = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
const easeOut = (x: number) => 1 - Math.pow(1 - x, 3);

/** The drug's place `elapsedMs` into the animation. Holds its last frame afterwards. */
export function dockFrame(verdict: BindingVerdict, elapsedMs: number): DockFrame {
  const t = clamp01(elapsedMs / DOCK_DURATION_MS[verdict]);
  if (verdict === "binds") {
    return { approach: easeInOut(t), tumble: 1 - easeInOut(clamp01(t * 1.15)) };
  }
  // Approach for the first 55%, then recoil with a decaying wobble.
  const split = 0.55;
  if (t < split) {
    const u = easeInOut(t / split);
    return { approach: REJECT_REACH * u, tumble: 1 - 0.55 * u };
  }
  const u = (t - split) / (1 - split);
  const wobble = Math.sin(u * Math.PI * 5) * (1 - u) * 0.04;
  return {
    approach: REJECT_REACH + (REJECT_REST - REJECT_REACH) * easeOut(u) + wobble,
    tumble: 0.45 + 0.35 * easeOut(u),
  };
}

/** Where the animation ends, for readers who prefer no motion. */
export function dockEndFrame(verdict: BindingVerdict): DockFrame {
  return dockFrame(verdict, DOCK_DURATION_MS[verdict]);
}

import { describe, expect, it } from "vitest";
import {
  DOCK_DURATION_MS,
  REJECT_REACH,
  REJECT_REST,
  dockEndFrame,
  dockFrame,
} from "./dockAnimation";

describe("dockFrame", () => {
  it("starts away from the pocket and tumbling, for both verdicts", () => {
    for (const verdict of ["binds", "does_not_bind"] as const) {
      expect(dockFrame(verdict, 0)).toEqual({ approach: 0, tumble: 1 });
    }
  });

  it("a drug that binds ends fully docked and aligned", () => {
    const end = dockEndFrame("binds");
    expect(end.approach).toBeCloseTo(1, 5);
    expect(end.tumble).toBeCloseTo(0, 5);
  });

  it("a drug that binds only ever moves forward", () => {
    let last = -1;
    for (let ms = 0; ms <= DOCK_DURATION_MS.binds; ms += 50) {
      const { approach } = dockFrame("binds", ms);
      expect(approach).toBeGreaterThanOrEqual(last);
      last = approach;
    }
  });

  it("a drug that doesn't bind gets close, then ends short of the pocket and unaligned", () => {
    let peak = 0;
    for (let ms = 0; ms <= DOCK_DURATION_MS.does_not_bind; ms += 25) {
      peak = Math.max(peak, dockFrame("does_not_bind", ms).approach);
    }
    expect(peak).toBeGreaterThan(REJECT_REACH - 0.02);
    expect(peak).toBeLessThan(1);
    const end = dockEndFrame("does_not_bind");
    expect(end.approach).toBeCloseTo(REJECT_REST, 1);
    expect(end.tumble).toBeGreaterThan(0.3);
  });

  it("holds its last frame after the end", () => {
    expect(dockFrame("binds", 99999)).toEqual(dockEndFrame("binds"));
  });
});

